 $r=Db::name('bet_records')->where('id',$recordId)->where('site_id',$site)->where('user_id',$user)->lock(true)->find();$d=Db::name('bet_details')->where('id',$id)->where('bet_record_id',$recordId)->lock(true)->find();if(!is_array($r)||!is_array($d)||$r['submission_id']!=$submission||(string)$r['issue_no']!==$issue||(float)$r['win_amount']!==$old||(float)$d['odds']!==300.0)throw new RuntimeException('组三九码目标校验失败');
