 $u=Db::name('site_users')->where('id',$user)->where('site_id',$site)->lock(true)->find();$ub=(float)$u['balance'];$ua=round($ub+$delta,2);Db::name('site_users')->where('id',$user)->update(['balance'=>number_format($ua,2,'.',''),'updated_at'=>date('Y-m-d H:i:s')]);CreditLedger::write(['tenant_id'=>1,'site_id'=>$site],null,'user',$user,$user,$recordId,null,$issue,$delta,$ub,$ua,'结算更正：组三九码赔率','manual_adjustment');
